'use strict';

const { execFile } = require('child_process');
const { promisify } = require('util');
const {
  createCh9329Input,
  probeNanoKvmDevice
} = require('..');

const execFileAsync = promisify(execFile);

function parseArgs(argv) {
  const options = {
    portPath: process.env.CH9329_PORT || process.env.NANOKVM_PORT || '/dev/cu.usbserial-130',
    baudRate: Number(process.env.CH9329_BAUD_RATE || 9600),
    stepDelayMs: Number(process.env.CH9329_STEP_DELAY_MS || 8),
    maxStepPx: Number(process.env.CH9329_MAX_STEP_PX || 25),
    screenWidth: Number(process.env.CH9329_SCREEN_WIDTH || 0),
    screenHeight: Number(process.env.CH9329_SCREEN_HEIGHT || 0)
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = argv[index + 1];
    if (arg === '--port' && next) {
      options.portPath = next;
      index += 1;
    } else if (arg === '--baud' && next) {
      options.baudRate = Number(next);
      index += 1;
    } else if (arg === '--delay' && next) {
      options.stepDelayMs = Number(next);
      index += 1;
    } else if (arg === '--max-step' && next) {
      options.maxStepPx = Number(next);
      index += 1;
    } else if (arg === '--screen-width' && next) {
      options.screenWidth = Number(next);
      index += 1;
    } else if (arg === '--screen-height' && next) {
      options.screenHeight = Number(next);
      index += 1;
    }
  }

  return options;
}

async function getCursorPosFromSystem() {
  if (process.platform !== 'darwin') {
    throw new Error(`cursor sampling is currently implemented for macOS only, got ${process.platform}`);
  }

  const { stdout } = await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'let p = NSEvent.mouseLocation',
      'let frame = NSScreen.screens.first?.frame ?? .zero',
      'print("\\(Int(p.x)),\\(Int(frame.height - p.y))")'
    ].join('\n')
  ]);
  const [x, y] = stdout.trim().split(',').map((value) => Number(value));
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    throw new Error(`invalid cursor output: ${stdout}`);
  }
  return { x, y };
}

async function getMainScreenSize() {
  if (process.platform !== 'darwin') {
    return { width: 1920, height: 1080 };
  }

  const { stdout } = await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'let frame = NSScreen.screens.first?.frame ?? .zero',
      'print("\\(Int(frame.width)),\\(Int(frame.height))")'
    ].join('\n')
  ]);
  const [width, height] = stdout.trim().split(',').map((value) => Number(value));
  if (!Number.isFinite(width) || !Number.isFinite(height)) {
    throw new Error(`invalid screen output: ${stdout}`);
  }
  return { width, height };
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const screen = await getMainScreenSize();
  const screenWidth = options.screenWidth || screen.width;
  const screenHeight = options.screenHeight || screen.height;
  const probe = await probeNanoKvmDevice(options.portPath, {
    baudRate: options.baudRate,
    probeTimeoutMs: 1500
  });
  console.log('probe', JSON.stringify(probe, null, 2));
  if (!probe.available) {
    throw new Error(`device probe failed: ${probe.reason || 'unknown error'}`);
  }

  const input = createCh9329Input({
    portPath: options.portPath,
    baudRate: options.baudRate,
    screenWidth,
    screenHeight,
    maxStepPx: options.maxStepPx,
    stepDelayMs: options.stepDelayMs,
    moveTimeoutMs: 2000,
    stallThreshold: 8,
    logger: null
  });

  await input.connect();
  try {
    console.log('screen', JSON.stringify({ width: screenWidth, height: screenHeight }));
    const cases = [
      ['right', 20, 0],
      ['left', -20, 0],
      ['down', 0, 20],
      ['up', 0, -20],
      ['right-small', 5, 0],
      ['down-small', 0, 5]
    ];

    for (const [name, dx, dy] of cases) {
      const before = await getCursorPosFromSystem();
      const target = { x: before.x + dx, y: before.y + dy };
      let status = 'ok';
      let error = '';

      try {
        await input.moveTo(target.x, target.y, getCursorPosFromSystem);
      } catch (moveError) {
        status = 'failed';
        error = moveError?.message || String(moveError);
      }

      await sleep(options.stepDelayMs);
      const after = await getCursorPosFromSystem();
      console.log(JSON.stringify({
        name,
        status,
        requested: { dx, dy },
        before,
        target,
        after,
        actual: { dx: after.x - before.x, dy: after.y - before.y },
        error
      }));
    }
  } finally {
    await input.disconnect();
  }
}

main().catch((error) => {
  console.error('[ch9329-diagnose] failed:', error);
  process.exitCode = 1;
});
